client_script:
frappe.web_form.on('resume_link', (field, value) => {
    if (!frappe.utils.is_url(value)) {
        frappe.msgprint(__('Resume link not valid'));
    }
});

frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

frappe.web_form.events.on("after_load", () => {
    const token = frappe.utils.get_url_arg("token");
    if (!token) return;

    frappe.call({
        method: "elmn.api.invitation.validate_and_start_invitation",
        args: { token },
        callback(r) {
            const result = r.message || {};
            if (!result.valid) {
                $(".web-form-wrapper").html(
                    '<div class="text-center" style="padding: 60px 20px;">' +
                    '<h4>' + __("This invitation link is no longer valid") + '</h4>' +
                    '<p>' + frappe.utils.escape_html(result.message || "") + '</p>' +
                    '<p>' + __("Please contact MLN for a new invitation link.") + '</p>' +
                    '</div>'
                );
                return;
            }
            frappe.web_form.set_values(Object.assign({ invitation_token: token }, result.prefill || {}));
        },
    });
});

frappe.web_form.events.on("after_load", () => {
    const geocode_field = frappe.web_form.fields_dict.geocode;
    if (!geocode_field || !geocode_field.$wrapper || !navigator.geolocation) return;

    const btn = $(
        '<button type="button" class="btn btn-xs btn-default" style="margin-top: 6px;">' +
        __("Use my current location") + '</button>'
    );
    geocode_field.$wrapper.append(btn);
    btn.on("click", () => {
        navigator.geolocation.getCurrentPosition((pos) => {
            frappe.web_form.set_value("geocode", pos.coords.latitude + "," + pos.coords.longitude);
        });
    });
});

frappe.web_form.events.on("after_load", () => {
    const field = frappe.web_form.fields_dict.commodities;
    if (!field || !field.grid) return;

    field.grid.get_field("commodity").get_query = (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];
        return { filters: row.commodity_category ? { item_group: row.commodity_category } : {} };
    };
});

frappe.web_form.events.on("after_load", () => {
    frappe.call({
        method: "elmn.api.vendor.get_vendor_registration_info",
        callback(r) {
            frappe.web_form._registration_info = r.message || {};
        },
    });

    const original_render_success_page = frappe.web_form.render_success_page.bind(frappe.web_form);
    frappe.web_form.render_success_page = function (data) {
        original_render_success_page(data);

        if (data.status === "Draft") {
            $(".success-title").text(__("Draft saved"));
            $(".success-message").text(
                __("We've emailed you a link to continue this application later. It stays available for {0} day(s).", [
                    data._draft_expiry_days || "",
                ])
            );
            return;
        }

        const info = frappe.web_form._registration_info || {};
        const categories = Array.from(
            new Set((data.commodities || []).map((row) => row.commodity_category).filter(Boolean))
        );
        const document_names = (data.documents || [])
            .filter((row) => row.attachment)
            .map((row) => row.document_type);

        const summary_rows = [
            [__("Reference Number"), frappe.utils.escape_html(data.name || "")],
            [__("Company"), frappe.utils.escape_html(data.legal_entity_name || "")],
            [__("Contact Email"), frappe.utils.escape_html(data.primary_contact_email || "")],
            [__("Categories"), frappe.utils.escape_html(categories.join(", "))],
            [__("Submitted"), data.creation ? frappe.datetime.str_to_user(data.creation) : ""],
        ];
        if (document_names.length) {
            summary_rows.push([__("Documents received"), frappe.utils.escape_html(document_names.join(", "))]);
        }

        const summary_html =
            '<div class="success-summary" style="border:1px solid var(--border-color, #e0e0e0);border-radius:8px;padding:16px 20px;margin-top:24px;">' +
            summary_rows
                .filter((row) => row[1])
                .map(
                    (row) =>
                        '<div style="display:flex;justify-content:space-between;gap:16px;padding:6px 0;">' +
                        '<span style="color:var(--text-muted, #8d99a6);">' + row[0] + '</span>' +
                        '<span style="font-weight:600;text-align:right;">' + row[1] + '</span>' +
                        '</div>'
                )
                .join("") +
            '</div>';

        const next_steps_text = info.expected_processing_days
            ? __(
                "MediLink's procurement and clinical teams will review your application (commercial vetting and product quality assessment run in parallel), typically within about {0} day(s). You will be notified by email at each stage. If approved, you will receive an account activation link.",
                [info.expected_processing_days]
            )
            : __(
                "MediLink's procurement and clinical teams will review your application (commercial vetting and product quality assessment run in parallel). You will be notified by email at each stage. If approved, you will receive an account activation link."
            );

        const contact = [info.support_email, info.support_phone].filter(Boolean).join(" / ");
        const contact_html = contact
            ? " " + __("Questions? Contact MediLink at {0}.", [frappe.utils.escape_html(contact)])
            : "";

        const next_steps_html =
            '<div class="success-next-steps" style="background:var(--bg-blue, #eaf2ff);border-radius:8px;padding:16px 20px;margin-top:20px;">' +
            '<b>' + __("What happens next?") + '</b> ' + next_steps_text + contact_html +
            '</div>';

        $(".success-message").after(summary_html + next_steps_html);

        $(".success-footer")
            .empty()
            .append(
                '<a href="/" class="btn btn-link">&larr; ' + __("Return to MediLink homepage") + '</a>'
            );
    };
});

frappe.web_form.events.on("after_load", () => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get("draft_token");
    if (!token) return;

    frappe.call({
        method: "elmn.api.vendor.resume_vendor_draft",
        args: { token },
        callback(r) {
            const result = r.message || {};
            if (!result.valid) {
                $(".web-form-wrapper").html(
                    '<div class="text-center" style="padding: 60px 20px;">' +
                    '<h4>' + __("This draft link is no longer valid") + '</h4>' +
                    '<p>' + frappe.utils.escape_html(result.message || "") + '</p>' +
                    '</div>'
                );
                return;
            }
            frappe.web_form._resuming_token = token;
            frappe.web_form.set_values(result.prefill || {});
        },
    });
});

frappe.web_form.events.on("after_load", () => {
    frappe.web_form._custom_save = function (is_draft) {
        const doc_values = this.get_values(true);
        if (!doc_values) return false;
        if (window.saving) return false;

        Object.assign(this.doc, doc_values);
        this.doc.doctype = this.doc_type;

        window.saving = true;
        frappe.form_dirty = false;

        frappe.call({
            type: "POST",
            method: "elmn.api.vendor.save_vendor_application",
            args: {
                data: this.doc,
                draft: is_draft ? 1 : 0,
                resuming_token: this._resuming_token || null,
            },
            freeze: true,
            callback: (response) => {
                if (!response.exc) {
                    this.handle_success(response.message);
                    frappe.web_form.events.trigger("after_save");
                }
            },
            always: () => {
                window.saving = false;
            },
        });
        return false;
    };

    frappe.web_form.save = function () {
        const is_last_page =
            !this.is_multi_step_form || this.current_section === this.page_breaks.length;
        return this._custom_save(!is_last_page);
    };

    const update_submit_label = () => {
        const is_last_page =
            !frappe.web_form.is_multi_step_form ||
            frappe.web_form.current_section === frappe.web_form.page_breaks.length;
        $(".submit-btn").text(is_last_page ? __("Submit Application") : __("Save as Draft"));
    };

    const original_toggle_buttons = frappe.web_form.toggle_buttons.bind(frappe.web_form);
    frappe.web_form.toggle_buttons = function () {
        original_toggle_buttons();
        update_submit_label();
    };

    update_submit_label();
});

frappe.web_form.events.on("after_load", () => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get("token");
    if (!token) {
        $(".web-form-wrapper").html(
            '<div class="text-center" style="padding: 60px 20px;">' +
            '<h4>' + __("Missing link") + '</h4>' +
            '<p>' + __("Please use the link from the email you received.") + '</p>' +
            '</div>'
        );
        return;
    }

    frappe.call({
        method: "elmn.api.vendor.resume_rfi_response",
        args: { token },
        callback(r) {
            const result = r.message || {};
            if (!result.valid) {
                $(".web-form-wrapper").html(
                    '<div class="text-center" style="padding: 60px 20px;">' +
                    '<h4>' + __("This link is no longer valid") + '</h4>' +
                    '<p>' + frappe.utils.escape_html(result.message || "") + '</p>' +
                    '</div>'
                );
                return;
            }
            frappe.web_form._response_token = token;
            frappe.web_form.set_values(result.prefill || {});
        },
    });
});

frappe.web_form.events.on("after_load", () => {
    frappe.web_form.save = function () {
        const doc_values = this.get_values(true);
        if (!doc_values) return false;
        if (window.saving) return false;
        if (!this._response_token) {
            frappe.msgprint(__("This link is invalid. Please use the link from the email you received."));
            return false;
        }

        window.saving = true;
        frappe.form_dirty = false;

        frappe.call({
            type: "POST",
            method: "elmn.api.vendor.submit_rfi_response",
            args: {
                token: this._response_token,
                items: doc_values.items || [],
            },
            freeze: true,
            callback: (response) => {
                if (!response.exc) {
                    this.handle_success(response.message);
                    frappe.web_form.events.trigger("after_save");
                }
            },
            always: () => {
                window.saving = false;
            },
        });
        return false;
    };
});
